  function firstSongGuideView(){return`<main class="music-studio-shell music-guide-window" aria-labelledby="firstSongWindowTitle"><header class="music-page-header"><p class="music-kicker">BEGINNER GUIDE</p><h1 id="firstSongWindowTitle">最初の1曲を作る</h1><p>Music Studio本体を操作しながら、このガイドを読み続けられます。</p><button type="button" class="music-primary" aria-label="Music Studio本体へ戻る" onclick="MusicStudio.focusMusicStudio()">← Music Studio本体へ戻る</button></header><section class="music-guide-window-content">${firstSongGuideContent()}</section></main>`}
